WITH RECURSIVE "_cte0" ("origin_id", "depth") AS (SELECT * FROM (SELECT CAST(:p12 AS uuid) AS "origin_id", CAST(:p13 AS bigint) AS "depth") AS "_recursive_anchor" UNION ALL SELECT "_t7"."target_id" AS "origin_id", ("_t0"."depth" + CAST(:p7 AS bigint)) AS "depth" FROM "_cte0" AS "_t0" CROSS JOIN LATERAL (SELECT "_t9"."id" AS "target_id", "_t8"."id" AS "edge_id", "_t9"."arch_type" AS "arch_type", "_t9"."arch_module" AS "arch_module", ROW_NUMBER() OVER (ORDER BY "_t8"."seq" ASC, "_t8"."id" ASC) AS "ord", COUNT(*) OVER () AS "arity" FROM "anchors" AS "_t8" INNER JOIN "anchors" AS "_t9" ON (("_t9"."id" = (CASE WHEN ("_t8"."src" = "_t0"."origin_id") THEN "_t8"."dst" ELSE "_t8"."src" END)) AND ("_t9"."kind" = CAST(:p0 AS text)) AND ((CAST(:p1 AS text) IS NULL) OR ("_t9"."arch_type" = CAST(:p1 AS text)) OR EXISTS (SELECT CAST(:p2 AS bigint) AS "one" FROM "graph_types" AS "_t10" WHERE (("_t10"."type_name" = "_t9"."arch_type") AND ("_t10"."ancestor" = CAST(:p1 AS text))))) AND CAST(:p3 AS boolean)) WHERE ((("_t8"."kind" = CAST(:p4 AS text)) AND (("_t8"."src" = "_t0"."origin_id") OR ("_t8"."undirected" AND ("_t8"."dst" = "_t0"."origin_id"))) AND ((CAST(:p5 AS text) IS NULL) OR ("_t8"."arch_type" = CAST(:p5 AS text)) OR EXISTS (SELECT CAST(:p6 AS bigint) AS "one" FROM "graph_types" AS "_t11" WHERE (("_t11"."type_name" = "_t8"."arch_type") AND ("_t11"."ancestor" = CAST(:p5 AS text)))))))) AS "_t7" WHERE (("_t7"."arity" = CAST(:p8 AS bigint)) AND ("_t7"."arch_type" = CAST(:p9 AS text)) AND ("_t7"."arch_module" = CAST(:p10 AS text)) AND ("_t0"."depth" < CAST(:p11 AS bigint)))) SELECT * FROM (SELECT CAST(:p22 AS bigint) AS "slot", "_t0"."depth" AS "depth", "_t0"."origin_id" AS "origin_id", "_t1"."target_id" AS "target_id", "_t1"."edge_id" AS "edge_id", "_t1"."arch_type" AS "arch_type", "_t1"."arch_module" AS "arch_module", "_t1"."ord" AS "ord", "_t1"."arity" AS "arity" FROM "_cte0" AS "_t0" LEFT JOIN LATERAL (SELECT "_t4"."id" AS "target_id", "_t3"."id" AS "edge_id", "_t4"."arch_type" AS "arch_type", "_t4"."arch_module" AS "arch_module", ROW_NUMBER() OVER (ORDER BY "_t3"."seq" ASC, "_t3"."id" ASC) AS "ord", COUNT(*) OVER () AS "arity" FROM "anchors" AS "_t3" INNER JOIN "anchors" AS "_t4" ON (("_t4"."id" = (CASE WHEN ("_t3"."src" = "_t0"."origin_id") THEN "_t3"."dst" ELSE "_t3"."src" END)) AND ("_t4"."kind" = CAST(:p15 AS text)) AND ((CAST(:p16 AS text) IS NULL) OR ("_t4"."arch_type" = CAST(:p16 AS text)) OR EXISTS (SELECT CAST(:p17 AS bigint) AS "one" FROM "graph_types" AS "_t5" WHERE (("_t5"."type_name" = "_t4"."arch_type") AND ("_t5"."ancestor" = CAST(:p16 AS text))))) AND CAST(:p18 AS boolean)) WHERE ((("_t3"."kind" = CAST(:p19 AS text)) AND (("_t3"."src" = "_t0"."origin_id") OR ("_t3"."undirected" AND ("_t3"."dst" = "_t0"."origin_id"))) AND ((CAST(:p20 AS text) IS NULL) OR ("_t3"."arch_type" = CAST(:p20 AS text)) OR EXISTS (SELECT CAST(:p21 AS bigint) AS "one" FROM "graph_types" AS "_t6" WHERE (("_t6"."type_name" = "_t3"."arch_type") AND ("_t6"."ancestor" = CAST(:p20 AS text)))))))) AS "_t1" ON CAST(:p14 AS boolean)) AS "_set" ("slot", "depth", "origin_id", "target_id", "edge_id", "arch_type", "arch_module", "ord", "arity") ORDER BY "slot" ASC, "depth" ASC, "ord" ASC LIMIT 2049
